message.content:
{
  "gate_token": "zJOgZEfl20-xxBPuOK8Utw",
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unrolls a map of the ruined royal city.",
      "visual_description": "A windswept hilltop at dusk, the cracked silhouette of a fallen capital below, a parchment map weighted down by a brass compass.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of cursed roads ahead.",
      "visual_description": "An oil lamp held aloft, its single flame-eye narrowed at distant black towers, sparks drifting in cold wind.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The tin fox scouts the broken castle gates.",
      "visual_description": "A small clockwork fox with blue glass eyes creeping along a shattered portcullis, key-wind tail ticking softly.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "Glass diver emerges from a cracked stained-glass window.",
      "visual_description": "A figure in a clear diving helmet steps from a tall cathedral window as if from water, coat shimmering with broken colored light.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "The team gathers beneath a torn royal banner.",
      "visual_description": "A faded crimson banner sags over rubble; four companions meet beneath it, lamp glow lighting their faces.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "Mara marks a route past the cursed tower.",
      "visual_description": "Inked fingers trace a path on parchment; in the background a spiral tower leans, windows glowing sickly green.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "The tin fox slips through an armored patrol.",
      "visual_description": "Polished boots and halberds in the foreground; between them a small metal fox darts low across wet cobblestones.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "Rumors of a great winged beast scatter frightened townsfolk.",
      "visual_description": "Empty market stalls, overturned baskets, a long scaled shadow stretched across a plaza wall while Mara watches from an alley.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "They find the sleeping tax collector slumped at a checkpoint.",
      "visual_description": "A round official snoring atop a ledger book, stamped papers stuck to his sleeves, a barrier arm half raised behind him.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "The oracle lamp whispers the password for a magic door.",
      "visual_description": "A tall iron door etched with runes glowing one by one as the lamp's flame-eye leans close, mouthing a silent word.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "Glass diver dives through a tall mirror into the dungeon.",
      "visual_description": "A gilded mirror ripples like a pond as the helmeted figure plunges in head-first, coat trailing reflections.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "Inside, the captive is found chained beneath the tower.",
      "visual_description": "A dim stone cell lit by lamp glow; rusted chains, a small barred window, the diver kneeling to pick a lock.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 13,
      "caption": "The tin fox triggers a distraction in the upper halls.",
      "visual_description": "Clockwork fox leaping across a chandelier chain, sending it crashing into a suit of empty armor in a marble corridor.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "Mara redraws the escape route on the fly.",
      "visual_description": "Ink smudges across the map as her quill races; the oracle lamp hovers close, casting a warm circle on the parchment.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "The sleeping tax collector accidentally blocks pursuit.",
      "visual_description": "A narrow archway jammed by the snoring official sprawled across a cart, ledger pages fluttering, boots thundering on the far side.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "Glass diver carries the rescued captive through a window of rain.",
      "visual_description": "A rain-streaked pane warps like liquid as the diver steps through with a cloaked figure in their arms.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 17,
      "caption": "The companions race across the trembling bridge.",
      "visual_description": "An old stone bridge over a black river, torches behind, dawn ahead, the tin fox sprinting in the lead with sparks from its tail.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "Beyond the city, Mara folds the map and smiles.",
      "visual_description": "A quiet hill at sunrise, the ruined capital small behind them, the lamp dimmed to a soft ember, the fox curled at Mara's boots.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox", "glass_diver"]
    }
  ]
}

